def compute(vars):
    income_tax_benefit = vars["v1"]
    share_based_compensation_cost = vars["v2"]

    try:
        ratio = income_tax_benefit / share_based_compensation_cost
    except ZeroDivisionError:
        return None

    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "income_tax_benefit": income_tax_benefit,
            "share_based_compensation_cost": share_based_compensation_cost,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
